`include "../QHMU_DEFINES.vh"

// ============================================================================
// QHMU_HDMI_TX
// APUG092 HDMI1.4b transmitter configured for 1920x1080p30.
//
// Timing:
//   HTOTAL 2200, HACTIVE 1920, HSA 44, HFP 88, HBP 148
//   VTOTAL 1125, VACTIVE 1080, VSA 5, VFP 4, VBP 36
//   VIDEO_VIC = 34 (1080p30)
//
// External RGB stream timing generated by QHMU_VIDEO_STREAMER uses the exact
// same counters/macros, which is essential for APUG092 O_video_locked.
// ============================================================================
module QHMU_HDMI_TX(
    input  wire        i_pixel_clk,
    input  wire        i_serial_clk,
    input  wire        i_rst,
    input  wire        i_hpd,

    input  wire        i_axis_user,
    input  wire        i_axis_valid,
    input  wire        i_axis_last,
    input  wire [23:0] i_axis_data,
    output wire        o_axis_ready,

    input  wire        i_audio_valid,
    input  wire [23:0] i_audio_left,
    input  wire [23:0] i_audio_right,

    input  wire        i_acr_valid,
    input  wire [19:0] i_acr_cts,
    input  wire [19:0] i_acr_n,

    output wire        o_video_locked,

    output wire        o_ddc_scl,
    inout  wire        io_ddc_sda,

    output wire        o_tmds_d0_p,
    output wire        o_tmds_d1_p,
    output wire        o_tmds_d2_p,
    output wire        o_tmds_clk_p
);
    wire [9:0] tmds_ch0;
    wire [9:0] tmds_ch1;
    wire [9:0] tmds_ch2;
    wire [9:0] tmds_clk;

    wire edid_valid;
    wire [7:0] edid_data;

    reg [23:0] edid_delay;
    reg edid_trigger;

    // Approximately 100 ms at 74.285714 MHz.
    localparam [23:0] EDID_DELAY_100MS = 24'd7_428_571;

    always @(posedge i_pixel_clk or posedge i_rst) begin
        if (i_rst) begin
            edid_delay   <= 24'd0;
            edid_trigger <= 1'b0;
        end else begin
            edid_trigger <= 1'b0;

            if (!i_hpd) begin
                edid_delay <= 24'd0;
            end else if (edid_delay != 24'hFFFFFF) begin
                edid_delay <= edid_delay + 1'b1;

                if (edid_delay == EDID_DELAY_100MS)
                    edid_trigger <= 1'b1;
            end
        end
    end

    hdmi_1_4b_transmitter_core_wrapper #(
        .DEVICE("EG"),

        .HTOTAL(`QHMU_HTOTAL),
        .HSA(`QHMU_HSA),
        .HFP(`QHMU_HFP),
        .HBP(`QHMU_HBP),
        .HACTIVE(`QHMU_HACTIVE),

        .VTOTAL(`QHMU_VTOTAL),
        .VSA(`QHMU_VSA),
        .VFP(`QHMU_VFP),
        .VBP(`QHMU_VBP),
        .VACTIVE(`QHMU_VACTIVE),

        .VIDEO_VIC(34),
        .VIDEO_TPG("Disable"),
        .VIDEO_FORMAT("RGB"),
        .AUDIO_SAMPLE_RATE("48K"),

        // ~399 kHz DDC clock at 74.285714 MHz:
        // 74.285714M / (2 * 93) = ~399.4 kHz.
        .IIC_SCL_DIV(93)
    ) u_core (
        .I_pixel_clk(i_pixel_clk),
        .I_rst(i_rst),

        .I_edid_read_trig(edid_trigger),
        .O_edid_read_valid(edid_valid),
        .O_edid_read_data(edid_data),

        .I_axis_s_user(i_axis_user),
        .I_axis_s_valid(i_axis_valid),
        .I_axis_s_last(i_axis_last),
        .I_axis_s_data(i_axis_data),
        .O_axis_s_ready(o_axis_ready),

        .I_audio_valid(i_audio_valid),
        .I_audio_left_data(i_audio_left),
        .I_audio_right_data(i_audio_right),

        .I_acr_valid(i_acr_valid),
        .I_acr_cts(i_acr_cts),
        .I_acr_n(i_acr_n),

        .O_video_locked(o_video_locked),

        .O_ddc_scl(o_ddc_scl),
        .IO_ddc_sda(io_ddc_sda),

        .O_ch0_tmds_data(tmds_ch0),
        .O_ch1_tmds_data(tmds_ch1),
        .O_ch2_tmds_data(tmds_ch2),
        .O_clk_tmds_data(tmds_clk)
    );

    QHMU_HDMI_PHY u_phy(
        .i_pixel_clk(i_pixel_clk),
        .i_serial_clk(i_serial_clk),
        .i_rst(i_rst),

        .i_tmds_ch0(tmds_ch0),
        .i_tmds_ch1(tmds_ch1),
        .i_tmds_ch2(tmds_ch2),
        .i_tmds_clk(tmds_clk),

        .o_tmds_d0_p(o_tmds_d0_p),
        .o_tmds_d1_p(o_tmds_d1_p),
        .o_tmds_d2_p(o_tmds_d2_p),
        .o_tmds_clk_p(o_tmds_clk_p)
    );

    wire _unused = edid_valid ^ ^edid_data;
endmodule
